const body = $json.body || {};
const call = body.call || {};
const analysis = call.call_analysis || {};
const cad = analysis.custom_analysis_data || {};
const fromNumber = call.from_number || '';
const toNumber = call.to_number || '';
const callId = call.call_id || '';
const zona = (cad.zona_interes || '').toString().trim();
const presMin = Number(cad.presupuesto_min || 0);
const presMax = Number(cad.presupuesto_max || 0);
const perfil = (cad.perfil_cliente || 'no_identificado').toString();
const visitaAgendada = !!cad.visita_agendada;
const motivoNoAgendada = (cad.motivo_no_agendada || '').toString();
const summary = (analysis.call_summary || '').toString();
const sentiment = (analysis.user_sentiment || '').toString();
const tieneInteresReal = !!(zona || presMin || presMax || (perfil && perfil !== 'no_identificado'));
return [{ json: { fromNumber, toNumber, callId, zona, presMin, presMax, perfil, visitaAgendada, motivoNoAgendada, summary, sentiment, tieneInteresReal } }];

const contactoResp = $input.first().json;
const datos = $('Extraer Análisis').first().json;
const contact = contactoResp._embedded.contacts[0];
let leadId = null;
if (contact._embedded && contact._embedded.leads && contact._embedded.leads.length) {
  leadId = contact._embedded.leads[0].id;
}
return [{ json: { ...datos, contactId: contact.id, leadId } }];

