={{ JSON.stringify([{
  name: 'Interés (voz IA) — ' + ($json.perfil || 'no_identificado'),
  pipeline_id: 13546071,
  status_id: 105137095,
  custom_fields_values: (function(){
    const cf = [{field_id: 1372569, values: [{value: 'Agente de voz — solo interés'}]}];
    if ($json.zona) cf.push({field_id: 1373285, values: [{value: $json.zona}]});
    if ($json.presMin) cf.push({field_id: 1376044, values: [{value: $json.presMin}]});
    if ($json.presMax) cf.push({field_id: 1376040, values: [{value: $json.presMax}]});
    if ($json.perfil && $json.perfil !== 'no_identificado') cf.push({field_id: 1379536, values: [{value: $json.perfil === 'comprador' ? 'compra' : $json.perfil === 'vendedor' ? 'venta' : $json.perfil === 'inversor' ? 'inversion' : $json.perfil}]});
    return cf;
  })(),
  _embedded: { contacts: [{ phone: $json.fromNumber }] }
}]) }}

